-- Error: Invalid column name 'total_with_tax'
SELECT id, total * 1.2 AS total_with_tax FROM orders WHERE total_with_tax > 100;

-- Fix: repeat the expression (or compute it in a CTE / subquery)
SELECT id, total * 1.2 AS total_with_tax FROM orders WHERE total * 1.2 > 100;

-- ORDER BY may use the alias
SELECT id, total * 1.2 AS total_with_tax FROM orders ORDER BY total_with_tax DESC;
